+func TestInstallerLookupRateLimitHeadersAllowTabs(t *testing.T) {
+	for name, line := range map[string]string{
+		"retry-after":           "Retry-After:\t120",
+		"x-ratelimit-remaining": "X-RateLimit-Remaining:\t0",
