122	// Without --version the installer asks the GitHub API for the newest release.
123	// Unauthenticated API calls are capped per IP address, and an exhausted cap
124	// answers 403 with x-ratelimit-remaining: 0. The installer used to fetch with
125	// curl -f and discard the error, so a rate-limited user was told to check
126	// their network (#555).
127	//
128	// runInstallerLookup runs the installer against a curl stub that answers the
129	// release lookup with the given status, headers and body the way real curl
130	// would: -f turns a 4xx/5xx into exit 22 with no output, -D writes the
131	// headers, -o writes the body and -w prints the status code. Anything past the
132	// lookup is the download, which the stub fails visibly, and an API URL other
133	// than the channel's lookup fails the same way. No network is used.
134	func runInstallerLookup(t *testing.T, status int, body string, headers map[string]string, networkDown bool, args ...string) (stdout, stderr string, err error) {
135		t.Helper()
136		var lines []string
137		for k, v := range headers {
138			lines = append(lines, k+": "+v)
139		}
140		return runInstallerLookupRawHeaders(t, status, body, lines, networkDown, args...)
141	}
142	
143	// runInstallerLookupRawHeaders is runInstallerLookup with the header lines
144	// written verbatim, for spellings a map cannot express (a tab after the colon).
145	// When the first line is a status line, the lines are the whole header dump,
146	// so a test can put a redirect's header block before the final response's.
147	func runInstallerLookupRawHeaders(t *testing.T, status int, body string, rawHeaders []string, networkDown bool, args ...string) (stdout, stderr string, err error) {
148		t.Helper()
149		if runtime.GOOS == "windows" {
150			t.Skip("installer is a POSIX shell script")
151		}
152		root, err := filepath.Abs("../..")
153		if err != nil {
154			t.Fatal(err)
155		}
156		dir := t.TempDir()
157		bin := filepath.Join(dir, "bin")
158		if err := os.Mkdir(bin, 0700); err != nil {
159			t.Fatal(err)
160		}
161		if err := os.WriteFile(filepath.Join(dir, "body"), []byte(body), 0600); err != nil {
162			t.Fatal(err)
163		}
164		headerLines := append([]string{fmt.Sprintf("HTTP/2 %d", status)}, rawHeaders...)
165		if len(rawHeaders) > 0 && strings.HasPrefix(rawHeaders[0], "HTTP/") {
166			headerLines = rawHeaders
167		}
168		if err := os.WriteFile(filepath.Join(dir, "headers"), []byte(strings.Join(headerLines, "\r\n")+"\r\n\r\n"), 0600); err != nil {
169			t.Fatal(err)
170		}
171		curl := `#!/bin/sh
172	fail=0; out=""; hdr=""; fmt=""; url=""
173	while [ "$#" -gt 0 ]; do
174	  case "$1" in
175	    -o) out="$2"; shift 2 ;;
176	    -D) hdr="$2"; shift 2 ;;
177	    -w) fmt="$2"; shift 2 ;;
178	    -*f*) fail=1; shift ;;
179	    -*) shift ;;
180	    *) url="$1"; shift ;;
181	  esac
182	done
183	case "$url" in
184	  https://api.github.com/*)
185	    [ "$url" = "$FIXTURE_API_URL" ] || { echo "unexpected API URL: $url (want $FIXTURE_API_URL)" >&2; exit 22; } ;;
186	  *) echo "download not stubbed: $url" >&2; exit 22 ;;
187	esac
188	if [ "$FIXTURE_NETWORK_DOWN" = 1 ]; then
189	  echo 'curl: (6) Could not resolve host: api.github.com' >&2
190	  [ -n "$fmt" ] && printf 000
191	  exit 6
192	fi
193	if [ "$fail" = 1 ] && [ "$FIXTURE_STATUS" -ge 400 ]; then
194	  echo "curl: (22) The requested URL returned error: $FIXTURE_STATUS" >&2
195	  exit 22
196	fi
197	[ -n "$hdr" ] && cp "$FIXTURE_DIR/headers" "$hdr"
198	if [ -n "$out" ]; then cp "$FIXTURE_DIR/body" "$out"; else cat "$FIXTURE_DIR/body"; fi
199	[ -n "$fmt" ] && printf '%s' "$FIXTURE_STATUS"
200	exit 0
201	`
202		if err := os.WriteFile(filepath.Join(bin, "curl"), []byte(curl), 0700); err != nil {
203			t.Fatal(err)
204		}
205		if err := os.WriteFile(filepath.Join(bin, "entire"), []byte("#!/bin/sh\nexit 0\n"), 0700); err != nil {
206			t.Fatal(err)
207		}
208		apiURL := "https://api.github.com/repos/entireio/entire-brain/releases/latest"
209		for _, arg := range args {
210			if arg == "--nightly" {
211				apiURL = "https://api.github.com/repos/entireio/entire-brain/releases?per_page=20"
212			}
213		}
214		down := "0"
215		if networkDown {
216			down = "1"
217		}
218		cmd := exec.Command("bash", append([]string{filepath.Join(root, "scripts/get-brain.sh")}, args...)...)
219		cmd.Env = append(os.Environ(), "PATH="+bin+string(os.PathListSeparator)+os.Getenv("PATH"), "FIXTURE_DIR="+dir, "FIXTURE_STATUS="+strconv.Itoa(status), "FIXTURE_NETWORK_DOWN="+down, "FIXTURE_API_URL="+apiURL, "WANT_VERSION=", "ENTIRE_BRAIN_INSTALL_DIR="+filepath.Join(dir, "install"), "NO_COLOR=1")
220		var outBuf, errBuf strings.Builder
221		cmd.Stdout, cmd.Stderr = &outBuf, &errBuf
222		err = cmd.Run()
223		return outBuf.String(), errBuf.String(), err
224	}
